/**
 * Refresh customer-edited ISAF documents with new configuration values.
 *
 * Documents generated by ISAF 5.3.26 or later carry tagged values (see
 * 03_Build_Engine/src/render_template/value_tags.js): each configuration value is an inline Word content
 * control tagged "ISAF.V:<key>", and the generated text of every key plus the document identity are stored
 * as Word document variables in word/settings.xml. Word keeps both when the customer edits and saves.
 *
 * refreshDocx(edited, fresh) takes the customer's document and the document ISAF has just generated from
 * the current configuration and templates, and returns the customer's document with:
 *  - every tagged value the customer has not changed replaced by the new value;
 *  - every tagged value the customer typed over kept as typed. When the configuration value also changed,
 *    the value is flagged with a Word comment ("ISAF refresh") and listed in the report. Earlier refresh
 *    comments stay until the customer deletes them; a value kept again with an unchanged configuration is
 *    not flagged again;
 *  - the stored values and identity updated to the fresh document's, so the next refresh compares against
 *    what ISAF generated this time.
 * Everything else in the body (the customer's own text, tables and formatting) is left as it is. Headers
 * and footers are ISAF's and are taken from the new document (owner, 24 November 2026).
 * A document the customer has not edited (body fingerprint unchanged, no value typed over) is replaced by
 * the new document whole, so template changes reach it.
 * New content that exists only in the fresh document (for example rows for a newly added software item)
 * cannot be inserted into the customer's structure; its keys are listed in the report.
 *
 * The format constants here must match value_tags.js (format "1"). This module is self-contained because
 * Customer editions ship the engine bundle without its sources.
 */
import PizZip from '../03_Build_Engine/node_modules/pizzip/js/index.js';

const TAG_PREFIX = 'ISAF.V:';
const VAR_PREFIX = 'ISAF_V_';
const FORMAT_VAR = 'ISAF_VALUES_FORMAT';
const IDENTITY_VAR = 'ISAF_DOC_IDENTITY';
const FINGERPRINT_VAR = 'ISAF_DOC_FINGERPRINT';
const COMMENT_AUTHOR = 'ISAF refresh';
const PARTS = /^word\/(document|header\d*|footer\d*|footnotes|endnotes)\.xml$/;
// Generated blocks: block-level controls the engine writes (stored as "#block:<tag>", see value_tags.js).
const BLOCK_TAGS = ['ISAF.DocumentReferences'];
const BLOCK_KEY_PREFIX = '#block:';
const INNER_SDT = /<w:sdt\b[^>]*>((?:(?!<w:sdt\b)[\s\S])*?)<\/w:sdt>/g;
const sdtTag = inner => { const m = inner.match(/<w:sdtPr>(?:(?!<\/w:sdtPr>)[\s\S])*?<w:tag w:val="([^"]*)"/); return m ? xmlUnesc(m[1]) : null; };

// Values ISAF manages itself (revision, dates and the like). They always take the new value; a
// difference there is not the customer's content.
// issue, status and release_date were removed (owner, 19 November 2026): the only fields with those names
// are Table 2-2's columns, which describe a SUPPLIER's document and are the customer's to fill. As
// managed keys they were silently overwritten on every refresh (SUPPLIER_TABLE_REFRESH_DEFECT.md).
// tests/managed-keys-regression.mjs fails if a template reuses a managed name outside its known places.
export const MANAGED_KEYS = new Set(['rev', 'revision', 'revision_description', 'issue_date', 'original_date', 'approval_date', 'initial_approval_date', 'initial_release_reference', 'copyright_year', 'doc_id', 'abbr', 'definition']);
const leafKey = key => key.slice(key.lastIndexOf('.') + 1);
// A [bracketed prompt] or the empty-configuration prompt (FILL_CONFIG_ITEM in value_tags.js): text the customer replaces.
const isPrompt = text => { const t = String(text || '').trim(); return /^\[[^\]]*\]$/.test(t) || t === '<fill config item>'; };

const xmlEsc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const xmlUnesc = s => String(s).replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16))).replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(Number(d))).replace(/&amp;/g, '&');

/** Visible text of WordprocessingML: w:t text, w:br/w:cr as new lines, w:tab as tabs. Deleted text is ignored. */
export function runText(xml) {
  let out = '';
  for (const m of String(xml).matchAll(/<w:t(?:\s[^>]*)?>([^<]*)<\/w:t>|<w:t\/>|<w:(br|cr)\b[^>]*\/>|<w:tab\/>/g)) {
    if (m[1] !== undefined) out += xmlUnesc(m[1]);
    else if (m[2]) out += '\n';
    else if (m[0] === '<w:tab/>') out += '\t';
  }
  return out;
}

function readVars(settingsXml) {
  const values = {}; let identity = null, format = null, fingerprint = null;
  for (const m of String(settingsXml || '').matchAll(/<w:docVar w:name="([^"]*)" w:val="([^"]*)"\s*\/>/g)) {
    const name = m[1], val = xmlUnesc(m[2]);
    if (name === FORMAT_VAR) format = val;
    else if (name === FINGERPRINT_VAR) fingerprint = val;
    else if (name === IDENTITY_VAR) { try { identity = JSON.parse(val); } catch {} }
    else if (name.startsWith(VAR_PREFIX)) { try { const { k, v } = JSON.parse(val); if (typeof k === 'string') values[k] = String(v ?? ''); } catch {} }
  }
  return { values, identity, format, fingerprint };
}

function openZip(bytes) {
  const zip = new PizZip(bytes);
  if (!zip.file('word/document.xml')) throw new Error('This file is not a Word document.');
  return zip;
}

/** ISAF identity and stored values of a .docx, or tagged:false when it was not generated with value tags. */
export function inspectDocx(bytes) {
  const zip = openZip(bytes);
  const { values, identity, format } = readVars(zip.file('word/settings.xml')?.asText());
  return { tagged: format === '1', identity, values };
}

// Elements that follow w:docVars in CT_Settings; docVars is inserted before the first one present.
const AFTER_DOCVARS = ['w:rsids', 'm:mathPr', 'w:attachedSchema', 'w:themeFontLang', 'w:clrSchemeMapping', 'w:doNotIncludeSubdocsInStats', 'w:doNotAutoCompressPictures', 'w:forceUpgrade', 'w:captions', 'w:readModeInkLockDown', 'w:smartTagType', 'sl:schemaLibrary', 'w:shapeDefaults', 'w:doNotEmbedSmartTags', 'w:decimalSymbol', 'w:listSeparator'];
function replaceIsafVars(settingsXml, varsXml) {
  let xml = settingsXml.replace(/<w:docVar w:name="ISAF_[^"]*" w:val="[^"]*"\s*\/>/g, '').replace(/<w:docVars>\s*<\/w:docVars>|<w:docVars\/>/g, '');
  if (/<w:docVars>/.test(xml)) return xml.replace(/<w:docVars>/, `<w:docVars>${varsXml}`);
  let at = -1;
  for (const tag of AFTER_DOCVARS) { const i = xml.search(new RegExp(`<${tag}[\\s>/]`)); if (i >= 0 && (at < 0 || i < at)) at = i; }
  if (at < 0) at = xml.lastIndexOf('</w:settings>');
  return xml.slice(0, at) + `<w:docVars>${varsXml}</w:docVars>` + xml.slice(at);
}
const varName = key => { let h = 2166136261; for (let i = 0; i < key.length; i++) { h ^= key.charCodeAt(i); h = Math.imul(h, 16777619) >>> 0; } return VAR_PREFIX + h.toString(36) + '_' + key.length.toString(36); };

function textRuns(open, rPr, text) {
  const pieces = String(text).split(/(\n|\t)/).filter(p => p !== '');
  const inner = pieces.map(p => p === '\n' ? '<w:br/>' : p === '\t' ? '<w:tab/>' : `<w:t xml:space="preserve">${xmlEsc(p)}</w:t>`).join('');
  return `${open}${rPr}${inner || '<w:t xml:space="preserve"></w:t>'}</w:r>`;
}

export function ensureCommentsPart(zip) {
  if (zip.file('word/comments.xml')) return;
  zip.file('word/comments.xml', '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n<w:comments xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"></w:comments>');
  const relsName = 'word/_rels/document.xml.rels';
  let rels = zip.file(relsName).asText();
  if (!/relationships\/comments"/.test(rels)) {
    let n = 1; while (rels.includes(`Id="rIdIsafC${n}"`)) n++;
    rels = rels.replace('</Relationships>', `<Relationship Id="rIdIsafC${n}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/comments" Target="comments.xml"/></Relationships>`);
    zip.file(relsName, rels);
  }
  let types = zip.file('[Content_Types].xml').asText();
  if (!types.includes('PartName="/word/comments.xml"')) {
    types = types.replace('</Types>', '<Override PartName="/word/comments.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.comments+xml"/></Types>');
    zip.file('[Content_Types].xml', types);
  }
}

/**
 * Store, as the generated values, what each value control and generated block of a document now shows.
 * Used after ISAF itself changes a generated document (revision stamping in the register), so a later
 * refresh does not mistake ISAF's own change for a customer edit. Returns the bytes unchanged when the
 * document has no ISAF value tags.
 */
export function syncStoredValues(bytes) {
  let zip; try { zip = openZip(bytes); } catch { return bytes; }
  const settings = zip.file('word/settings.xml')?.asText() || '';
  const before = readVars(settings);
  if (before.format !== '1') return bytes;
  const values = {};
  for (const name of Object.keys(zip.files)) {
    if (!PARTS.test(name)) continue;
    for (const m of zip.file(name).asText().matchAll(INNER_SDT)) {
      const t = sdtTag(m[1]);
      const key = t?.startsWith(TAG_PREFIX) ? t.slice(TAG_PREFIX.length) : BLOCK_TAGS.includes(t) ? BLOCK_KEY_PREFIX + t : null;
      if (key && !Object.hasOwn(values, key)) values[key] = runText(/<w:sdtContent>([\s\S]*)<\/w:sdtContent>/.exec(m[1])?.[1] ?? '');
    }
  }
  const same = Object.keys(values).length === Object.keys(before.values).length && Object.entries(values).every(([k, v]) => before.values[k] === v);
  if (same) return bytes;
  zip.file('word/settings.xml', replaceIsafVars(settings, isafVarsXml(values, before.identity)));
  return zip.generate({ type: 'nodebuffer', compression: 'DEFLATE' });
}
const isafVarsXml = (values, identity) => [`<w:docVar w:name="${FORMAT_VAR}" w:val="1"/>`]
  .concat(identity ? [`<w:docVar w:name="${IDENTITY_VAR}" w:val="${xmlEsc(JSON.stringify(identity))}"/>`] : [])
  .concat(Object.entries(values).map(([k, v]) => `<w:docVar w:name="${varName(k)}" w:val="${xmlEsc(JSON.stringify({ k, v }))}"/>`)).join('');

/**
 * Fingerprint of a generated body: its text outside value controls, generated blocks and Word fields.
 * Must match bodyFingerprint() in 03_Build_Engine/src/render_template/value_tags.js, which stores it as
 * ISAF_DOC_FINGERPRINT when a document is built.
 */
export function bodyFingerprint(documentXml) {
  let xml = String(documentXml || ""), prev;
  const inner = /<w:sdt\b[^>]*>((?:(?!<w:sdt\b)[\s\S])*?)<\/w:sdt>/g;
  do {
    prev = xml;
    xml = xml.replace(inner, (sdt, body) => {
      const m = body.match(/<w:sdtPr>(?:(?!<\/w:sdtPr>)[\s\S])*?<w:tag w:val="([^"]*)"/);
      const tag = m ? m[1] : "";
      return tag.startsWith("ISAF.V:") || tag === "ISAF.DocumentReferences" ? "" : sdt;
    });
  } while (xml !== prev);
  xml = xml.replace(/<w:fldSimple\b[^>]*>[\s\S]*?<\/w:fldSimple>/g, "");
  let depth = 0, text = "";
  for (const m of xml.matchAll(/<w:fldChar\b[^>]*w:fldCharType="(begin|end)"[^>]*\/>|<w:t(?:\s[^>]*)?>([^<]*)<\/w:t>/g)) {
    if (m[1] === "begin") depth++;
    else if (m[1] === "end") depth = Math.max(0, depth - 1);
    else if (!depth) text += m[2];
  }
  text = text.replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16))).replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(Number(d))).replace(/&amp;/g, "&").replace(/\s+/g, " ").trim();
  let h1 = 0x811c9dc5, h2 = 0x01000193;
  for (let i = 0; i < text.length; i++) { const c = text.charCodeAt(i); h1 = Math.imul(h1 ^ c, 16777619) >>> 0; h2 = Math.imul(h2 ^ c, 2246822519) >>> 0; }
  return `1:${text.length.toString(36)}:${h1.toString(36)}:${h2.toString(36)}`;
}

/**
 * Texts each value key shows in a document. A key whose controls show different texts in the generated
 * document cannot be refreshed control by control, because the stored value is the first control's
 * text only, so such a key cannot be compared or refreshed control by control: the abbreviation rows
 * (every row is tagged abbr / definition) and the occasional value written in two layouts.
 */
function valueTexts(zip) {
  const texts = new Map();
  for (const name of Object.keys(zip.files)) {
    if (!PARTS.test(name)) continue;
    for (const m of zip.file(name).asText().matchAll(INNER_SDT)) {
      const tag = sdtTag(m[1]);
      if (!tag?.startsWith(TAG_PREFIX)) continue;
      const k = tag.slice(TAG_PREFIX.length);
      if (!texts.has(k)) texts.set(k, new Set());
      texts.get(k).add(runText(/<w:sdtContent>([\s\S]*)<\/w:sdtContent>/.exec(m[1])?.[1] ?? ''));
    }
  }
  return texts;
}

/** The table holding a value control tagged key, as [start, end) in xml, or null. */
function tableWith(xml, key) {
  const at = xml.indexOf(`<w:tag w:val="${TAG_PREFIX}${key}"/>`);
  if (at < 0) return null;
  const start = Math.max(xml.lastIndexOf('<w:tbl>', at), xml.lastIndexOf('<w:tbl ', at));
  const end = xml.indexOf('</w:tbl>', at);
  if (start < 0 || end < 0 || xml.slice(start + 6, at).includes('<w:tbl>')) return null;
  return [start, end + '</w:tbl>'.length];
}

/**
 * The LIST OF ABBREVIATIONS table is ISAF's (abbr and definition are managed keys): it is replaced whole by
 * the newly generated table, which lists the abbreviations the current document uses. Before 24 November 2026
 * the refresh wrote the first abbreviation into every row (all rows share the keys abbr and definition).
 */
function replaceAbbreviationTable(zip, freshZip) {
  const xml = zip.file('word/document.xml').asText(), freshXml = freshZip.file('word/document.xml').asText();
  const a = tableWith(xml, 'abbr'), b = tableWith(freshXml, 'abbr');
  if (!a || !b) return false;
  zip.file('word/document.xml', xml.slice(0, a[0]) + freshXml.slice(b[0], b[1]) + xml.slice(a[1]));
  return true;
}

/**
 * A document built before fingerprints (ISAF 6.0.4 and earlier) that no editor has saved since: ISAF writes
 * the same created and modified times and an ISAF (or unnamed) last author; Word, LibreOffice and Google Docs
 * update both on save.
 */
function neverSaved(zip) {
  const core = zip.file('docProps/core.xml')?.asText() || '';
  const created = /<dcterms:created\b[^>]*>([^<]*)</.exec(core)?.[1], modified = /<dcterms:modified\b[^>]*>([^<]*)</.exec(core)?.[1];
  const by = (/<cp:lastModifiedBy>([^<]*)</.exec(core)?.[1] ?? '').trim();
  return !!created && created === modified && ['ISAF', 'Un-named', ''].includes(by);
}

/** Take the body fingerprint again after a build step that adds generated content (imported requirements). */
export function restampFingerprint(bytes) {
  const zip = openZip(bytes), settings = zip.file('word/settings.xml')?.asText() || '';
  const re = new RegExp(`<w:docVar w:name="${FINGERPRINT_VAR}" w:val="[^"]*"\\s*/>`);
  if (!re.test(settings)) return bytes;
  zip.file('word/settings.xml', settings.replace(re, `<w:docVar w:name="${FINGERPRINT_VAR}" w:val="${bodyFingerprint(zip.file('word/document.xml').asText())}"/>`));
  return zip.generate({ type: 'nodebuffer', compression: 'DEFLATE' });
}

/** Keys of value controls and generated blocks whose text the customer changed (neither the stored nor the new value). */
function changedValues(zip, oldValues, newValues, freshTexts) {
  const changed = [];
  for (const name of Object.keys(zip.files)) {
    if (!PARTS.test(name)) continue;
    for (const m of zip.file(name).asText().matchAll(INNER_SDT)) {
      const tag = sdtTag(m[1]);
      if (!tag) continue;
      const k = BLOCK_TAGS.includes(tag) ? BLOCK_KEY_PREFIX + tag : tag.startsWith(TAG_PREFIX) ? tag.slice(TAG_PREFIX.length) : null;
      if (k === null) continue;
      const current = runText(/<w:sdtContent>([\s\S]*)<\/w:sdtContent>/.exec(m[1])?.[1] ?? '');
      if (freshTexts.get(k)?.has(current) || current === oldValues[k] || current === newValues[k] || MANAGED_KEYS.has(leafKey(k)) || isPrompt(current)) continue;
      changed.push(k);
    }
  }
  return changed;
}

const relsOf = part => part.replace(/^(.*\/)([^/]+)$/, '$1_rels/$2.rels');
const relList = xml => [...String(xml || '').matchAll(/<Relationship\b[^>]*\/?>/g)].map(m => ({ xml: m[0], id: /\bId="([^"]*)"/.exec(m[0])?.[1], type: /\bType="([^"]*)"/.exec(m[0])?.[1] || '', target: /\bTarget="([^"]*)"/.exec(m[0])?.[1], external: /TargetMode="External"/.test(m[0]) }));

/**
 * Headers and footers are ISAF's (owner, 24 November 2026): an edited document takes them from the newly
 * generated document, so export control, distribution statement and approval header follow the current
 * templates and configuration. Matched by relationship id and type; the part's own relationships (for
 * example a logo) and their media are copied with it. Returns the number of parts replaced.
 */
function replaceHeadersFooters(zip, freshZip) {
  const editedRels = relList(zip.file('word/_rels/document.xml.rels')?.asText());
  const freshRels = new Map(relList(freshZip.file('word/_rels/document.xml.rels')?.asText()).map(r => [r.id, r]));
  let types = zip.file('[Content_Types].xml')?.asText() || '';
  let replaced = 0, n = 0;
  for (const r of editedRels) {
    if (!/\/(header|footer)$/.test(r.type) || r.external) continue;
    const f = freshRels.get(r.id);
    if (!f || f.type !== r.type || f.external) continue;
    const editedPart = 'word/' + r.target.replace(/^\.?\//, ''), freshPart = 'word/' + f.target.replace(/^\.?\//, '');
    const freshFile = freshZip.file(freshPart);
    if (!freshFile || !zip.file(editedPart)) continue;
    zip.file(editedPart, freshFile.asText());
    const freshPartRels = freshZip.file(relsOf(freshPart));
    if (freshPartRels) {
      let relsXml = freshPartRels.asText();
      for (const pr of relList(relsXml)) {
        if (pr.external || !pr.target) continue;
        const src = freshZip.file('word/' + pr.target.replace(/^\.?\//, ''));
        if (!src) continue;
        const ext = (pr.target.match(/\.([A-Za-z0-9]+)$/) || [])[1] || 'bin';
        let target;
        do target = `media/isaf_hf_${++n}.${ext}`; while (zip.file('word/' + target));
        zip.file('word/' + target, src.asUint8Array());
        relsXml = relsXml.replace(pr.xml, pr.xml.replace(/\bTarget="[^"]*"/, `Target="${target}"`));
        if (!new RegExp(`<Default Extension="${ext}"`, 'i').test(types)) {
          const ct = (freshZip.file('[Content_Types].xml')?.asText().match(new RegExp(`<Default Extension="${ext}" ContentType="[^"]*"\\/>`, 'i')) || [])[0];
          if (ct) types = types.replace(/<Types\b[^>]*>/, m => m + ct);
        }
      }
      zip.file(relsOf(editedPart), relsXml);
    } else if (zip.file(relsOf(editedPart))) zip.remove(relsOf(editedPart));
    replaced++;
  }
  if (types) zip.file('[Content_Types].xml', types);
  return replaced;
}

/**
 * Refresh an edited ISAF document. edited, fresh: .docx bytes. Returns { bytes, report }.
 * report: { identity, updated, unchanged, kept[], conflicts[], filled[], removed[], notInDocument[], replaced, headersFooters }.
 * replaced: true when the document was unedited and the new document is returned whole.
 * headersFooters: number of header and footer parts taken from the new document (edited documents).
 * Throws when either document has no ISAF value tags.
 */
export function refreshDocx(edited, fresh, { comments = true, date = new Date().toISOString().replace(/\.\d+Z$/, 'Z') } = {}) {
  const zip = openZip(edited), freshZip = openZip(fresh);
  const editedSettings = zip.file('word/settings.xml')?.asText() || '';
  const freshSettings = freshZip.file('word/settings.xml')?.asText() || '';
  const before = readVars(editedSettings), after = readVars(freshSettings);
  if (before.format !== '1') throw new Error('This document was not generated with ISAF value tags (ISAF 5.3.26 or later), so its values cannot be refreshed.');
  if (after.format !== '1') throw new Error('The newly generated document has no ISAF value tags.');
  const oldValues = before.values, newValues = after.values;
  const report = { identity: after.identity, previousIdentity: before.identity, updated: 0, unchanged: 0, kept: [], conflicts: [], filled: [], removed: [], notInDocument: [] };
  const seen = new Set(), flagged = [];

  // Unedited document: its body still matches what ISAF generated (stored fingerprint; for a document built
  // before fingerprints, never saved by an editor or identical to the new body) and no value was typed over. It is replaced by the new document whole, so template changes reach it.
  const freshTexts = valueTexts(freshZip);
  const editedDoc = zip.file('word/document.xml')?.asText() || '';
  const editedPrint = bodyFingerprint(editedDoc);
  // Imported requirement tables that the new document does not carry are kept (refresh, not replacement).
  const importsOnlyHere = editedDoc.includes('w:val="ISAF.Import:') && !freshZip.file('word/document.xml')?.asText().includes('w:val="ISAF.Import:');
  const unedited = !importsOnlyHere && (before.fingerprint ? editedPrint === before.fingerprint : neverSaved(zip) || editedPrint === bodyFingerprint(freshZip.file('word/document.xml')?.asText()))
    && !changedValues(zip, oldValues, newValues, freshTexts).length;
  if (unedited) return { bytes: Buffer.from(fresh), report: { ...report, replaced: true } };
  report.replaced = false;
  report.headersFooters = replaceHeadersFooters(zip, freshZip);
  replaceAbbreviationTable(zip, freshZip);
  const varied = new Set([...freshTexts].filter(([, t]) => t.size > 1).map(([k]) => k));

  // Newly generated blocks, to replace unedited blocks whole.
  const freshBlocks = new Map();
  for (const m of (freshZip.file('word/document.xml').asText()).matchAll(INNER_SDT)) { const t = sdtTag(m[1]); if (BLOCK_TAGS.includes(t) && !freshBlocks.has(t)) freshBlocks.set(t, m[0]); }

  for (const name of Object.keys(zip.files)) {
    if (!PARTS.test(name)) continue;
    const xml = zip.file(name).asText();
    if (!xml.includes(TAG_PREFIX) && !BLOCK_TAGS.some(t => xml.includes(t))) continue;
    const isBody = name === 'word/document.xml';
    // Innermost content controls only: ISAF value controls hold runs, never other controls.
    const out = xml.replace(INNER_SDT, (sdt, inner) => {
      const key = sdtTag(inner);
      if (!key) return sdt;
      if (BLOCK_TAGS.includes(key)) {
        const k = BLOCK_KEY_PREFIX + key, fresh = freshBlocks.get(key);
        if (!fresh || !Object.hasOwn(newValues, k)) return sdt;
        seen.add(k);
        const current = runText(/<w:sdtContent>([\s\S]*)<\/w:sdtContent>/.exec(inner)?.[1] ?? ''), old = oldValues[k], neu = newValues[k];
        if (current === neu) { report.unchanged++; return sdt; }
        if (Object.hasOwn(oldValues, k) && current === old) { report.updated++; return fresh; }
        if (neu === old) { report.kept.push({ key: k, text: '(your edited block)', generated: '' }); return sdt; }
        const conflict = { key: k, text: '(your edited block)', previous: null, generated: '(updated block; see a new template draft)', part: name.slice(5), block: true };
        report.conflicts.push(conflict);
        if (comments && isBody) { flagged.push(conflict); return sdt.replace(/(<w:p\b[^>]*>(?:<w:pPr>(?:(?!<\/w:pPr>)[\s\S])*<\/w:pPr>)?)([\s\S]*?)(<\/w:p>)/, (m, a, b, c) => `${a}\u0000ISAFC${flagged.length - 1}\u0000${b}\u0000ISAFE${flagged.length - 1}\u0000${c}`); }
        return sdt;
      }
      if (!key.startsWith(TAG_PREFIX)) return sdt;
      const k = key.slice(TAG_PREFIX.length);
      seen.add(k);
      const contentMatch = inner.match(/<w:sdtContent>([\s\S]*)<\/w:sdtContent>/);
      if (!contentMatch) return sdt;
      const content = contentMatch[1], current = runText(content);
      const hasOld = Object.hasOwn(oldValues, k), old = oldValues[k], hasNew = Object.hasOwn(newValues, k), neu = newValues[k];
      const replace = text => {
        const open = (content.match(/<w:r\b[^>]*>/) || ['<w:r>'])[0].replace(/<w:r\b[^>]*>/, m => m.endsWith('/>') ? '<w:r>' : m);
        const rPr = (content.match(/<w:r\b[^>]*>\s*(<w:rPr>(?:(?!<\/w:rPr>)[\s\S])*<\/w:rPr>|<w:rPr\/>)/) || [])[1] || '';
        const sdtPr = inner.match(/<w:sdtPr>[\s\S]*?<\/w:sdtPr>/)[0].replace(/<w:showingPlcHdr\/>/g, '');
        const rest = inner.replace(/<w:sdtPr>[\s\S]*?<\/w:sdtPr>/, '').replace(/<w:sdtContent>[\s\S]*<\/w:sdtContent>/, '');
        return sdt.replace(inner, () => `${sdtPr}${rest}<w:sdtContent>${textRuns(open, rPr, text)}</w:sdtContent>`);
      };
      if (!hasNew) { report.removed.push({ key: k, text: current }); return sdt; }
      if (varied.has(k)) { report.unchanged++; return sdt; }
      if (current === neu) { report.unchanged++; return sdt; }
      if (MANAGED_KEYS.has(leafKey(k))) { report.updated++; return replace(neu); }
      if (hasOld && current === old) { report.updated++; return replace(neu); }
      // The customer changed this value.
      if (hasOld && isPrompt(old) && neu === old) { report.filled.push({ key: k, text: current }); return sdt; }
      if (hasOld && neu === old) { report.kept.push({ key: k, text: current, generated: old }); return sdt; }
      const conflict = { key: k, text: current, previous: hasOld ? old : null, generated: neu, part: name.slice(5) };
      report.conflicts.push(conflict);
      if (comments && isBody) { flagged.push(conflict); return `\u0000ISAFC${flagged.length - 1}\u0000${sdt}\u0000ISAFE${flagged.length - 1}\u0000`; }
      return sdt;
    });
    zip.file(name, out);
  }

  // Flag conflicts with Word comments anchored on the value.
  if (flagged.length) {
    ensureCommentsPart(zip);
    let commentsXml = zip.file('word/comments.xml').asText();
    let doc = zip.file('word/document.xml').asText();
    const used = [...commentsXml.matchAll(/w:id="(\d+)"/g), ...doc.matchAll(/<w:comment(?:RangeStart|RangeEnd|Reference) w:id="(\d+)"/g)].map(m => Number(m[1]));
    let next = (used.length ? Math.max(...used) : -1) + 1;
    const added = [];
    doc = doc.replace(/\u0000ISAF([CE])(\d+)\u0000/g, (_, kind, i) => {
      const c = flagged[Number(i)];
      if (c.id === undefined) c.id = next++;
      return kind === 'C' ? `<w:commentRangeStart w:id="${c.id}"/>` : `<w:commentRangeEnd w:id="${c.id}"/><w:r><w:rPr><w:rStyle w:val="CommentReference"/></w:rPr><w:commentReference w:id="${c.id}"/></w:r>`;
    });
    for (const c of flagged) {
      const was = c.previous === null ? 'was not recorded' : `was "${c.previous}"`;
      const text = c.block
        ? 'ISAF refresh: the configuration changes this generated section (for example document numbers or revisions), but you edited it, so your version was kept. Compare it with a new template draft and update it if needed, then delete this comment.'
        : `ISAF refresh: the configuration value for this field is now "${c.generated}" (it ${was}). Your text was kept. Update it if needed, then delete this comment.`;
      added.push(`<w:comment w:id="${c.id}" w:author="${COMMENT_AUTHOR}" w:date="${date}" w:initials="ISAF"><w:p><w:r><w:t xml:space="preserve">${xmlEsc(text)}</w:t></w:r></w:p></w:comment>`);
    }
    commentsXml = commentsXml.replace(/<\/w:comments>\s*$/, `${added.join('')}</w:comments>`);
    zip.file('word/comments.xml', commentsXml);
    zip.file('word/document.xml', doc);
  }

  // New values that the fresh document shows but the customer's document has no control for.
  const freshKeys = new Set();
  for (const name of Object.keys(freshZip.files)) {
    if (!PARTS.test(name)) continue;
    for (const m of freshZip.file(name).asText().matchAll(/<w:tag w:val="ISAF\.V:([^"]*)"/g)) freshKeys.add(xmlUnesc(m[1]));
  }
  for (const k of freshKeys) if (!seen.has(k) && Object.hasOwn(newValues, k)) report.notInDocument.push({ key: k, text: newValues[k] });

  // Store what ISAF generated this time (keeping values of controls that no longer exist in the configuration).
  const stored = { ...newValues };
  for (const r of report.removed) if (Object.hasOwn(oldValues, r.key)) stored[r.key] = oldValues[r.key];
  const printXml = after.fingerprint ? `<w:docVar w:name="${FINGERPRINT_VAR}" w:val="${xmlEsc(after.fingerprint)}"/>` : '';
  zip.file('word/settings.xml', replaceIsafVars(editedSettings, printXml + isafVarsXml(stored, after.identity)));
  for (const name of Object.keys(zip.files)) if (zip.files[name].dir) delete zip.files[name];
  return { bytes: zip.generate({ type: 'nodebuffer', compression: 'DEFLATE' }), report };
}

/**
 * Match previously edited documents to the documents of a build.
 * previous: [{ name, bytes }]. artifacts: [{ key, id, item, pn }].
 * Match order: same document PN (same program); then same document type and item (for example a new
 * program reusing a previous program's documents); then the only document of that type on both sides.
 * Returns { matches: Map(artifact key -> { name, bytes, identity, how }), unmatched: [{ name, reason }] }.
 */
export function matchPrevious(previous, artifacts) {
  const matches = new Map(), unmatched = [], pool = [];
  for (const file of previous || []) {
    try {
      const info = inspectDocx(file.bytes);
      if (!info.tagged || !info.identity?.doc) { unmatched.push({ name: file.name, reason: 'No ISAF value tags (generated before ISAF 5.3.26, or not an ISAF document).' }); continue; }
      pool.push({ ...file, identity: info.identity });
    } catch (e) { unmatched.push({ name: file.name, reason: e.message || 'Could not be read as a Word document.' }); }
  }
  const take = (a, file, how) => { matches.set(a.key, { name: file.name, bytes: file.bytes, identity: file.identity, how }); pool.splice(pool.indexOf(file), 1); };
  const lower = s => String(s || '').toLowerCase();
  for (const a of artifacts) {
    const file = pool.find(f => lower(f.identity.pn) && lower(f.identity.pn) === lower(a.pn) && f.identity.doc === a.id);
    if (file) take(a, file, 'document PN');
  }
  for (const a of artifacts) {
    if (matches.has(a.key)) continue;
    const file = pool.find(f => f.identity.doc === a.id && String(f.identity.item || '') === String(a.item || ''));
    if (file) take(a, file, 'document type and item');
  }
  for (const a of artifacts) {
    if (matches.has(a.key)) continue;
    const sameType = pool.filter(f => f.identity.doc === a.id), sameBuild = artifacts.filter(x => x.id === a.id && !matches.has(x.key));
    if (sameType.length === 1 && sameBuild.length === 1) take(a, sameType[0], 'document type');
  }
  for (const f of pool) unmatched.push({ name: f.name, reason: `No matching document in this build (${f.identity.doc}${f.identity.item ? ' for ' + f.identity.item : ''}, ${f.identity.pn || 'no PN'}).` });
  return { matches, unmatched };
}

const short = (s, n = 70) => { const t = String(s ?? '').replace(/\s+/g, ' '); return t.length > n ? t.slice(0, n - 1) + '…' : t; };
/**
 * Plain-text refresh report for the build output.
 * entries: [{ pn, name, how, label, candidate, reused, summary: { updated, kept, flagged, notPlaced }, flagged: [{ key, text, generated }], notPlaced: [key] }].
 */
export function refreshReportText(entries, unmatched = []) {
  const lines = ['ISAF document refresh report', '', 'Your edited documents were refreshed with the current configuration. Values you had not changed were', 'updated. Values you had changed were kept; where the configuration value also changed, the value is', 'flagged with a Word comment from "ISAF refresh" and listed below. Other text in the body is not changed;', 'headers and footers are taken from the current template. Documents you had not edited are replaced', 'with the newly generated document.', ''];
  for (const e of entries) {
    const s = e.summary || {};
    lines.push(`${e.pn}  ${e.label ? 'Rev ' + e.label + '  ' : ''}(from ${e.name}${e.how ? ', matched by ' + e.how : ''})`);
    if (e.reused) lines.push('  Already refreshed from this document with this configuration; the earlier refreshed version is used.');
    if (e.candidate) lines.push('  Saved for review (Pending review): accept or reject it in Program Documents.');
    if (s.replaced) { lines.push('  Not edited since ISAF generated it: replaced with the newly generated document.', ''); continue; }
    lines.push(`  ${s.updated || 0} values updated, ${s.kept || 0} of your changes kept, ${s.flagged || 0} flagged.${s.headersFooters ? ' Header and footer taken from the current template.' : ''}`);
    for (const c of e.flagged || []) lines.push(`  FLAGGED ${c.key}: your text "${short(c.text)}"; configuration now "${short(c.generated)}"`);
    if (s.notPlaced) lines.push(`  ${s.notPlaced} new values have no place in your document (for example rows for a new item). Compare with a new template draft: ${(e.notPlaced || []).join(', ')}${s.notPlaced > (e.notPlaced || []).length ? ', …' : ''}`);
    lines.push('');
  }
  if (unmatched.length) { lines.push('Files not used:'); for (const u of unmatched) lines.push(`  ${u.name}: ${u.reason}`); lines.push(''); }
  return lines.join('\n');
}
